card.innerHTML='<div class="cap">Organization artifacts</div><h2>Add and review MCP, Skill, or Agent sources</h2><p class="help">One shared workspace handles MCPs, Skills, and Agents. Add items individually or import one batch, scan each unique exact source once, and review evidence. This preflight intake explicitly declares that it is not authority, does not choose authorized targets, and does not infer launch or transport.</p><div class="artifact-capacity" aria-label="Artifact workflow capacity"><div><strong id="artifact-candidate-count">0 / 100 candidates</strong><span class="help">One mixed intake file for MCPs, Skills, and Agents.</span></div><div><strong>64 decisions per protected file</strong><span class="help">A 100-item intake may require two protected files if every item is approved.</span></div></div><section class="artifact-stage" aria-labelledby="artifact-add-title"><h3 class="artifact-stage-title" id="artifact-add-title">1. Add exact sources to the review queue</h3><p class="help">Use one accountable owner email for the batch. Marketplace and directory links help discovery only; the canonical npm package/version or GitHub repository/commit/path becomes the source. Authorized targets are chosen later, only in the protected policy step. Execution details must come from separately observed evidence or an explicit organization decision; an npm package is never silently treated as stdio/npx.</p><p class="help">Find candidates: <a href="https://www.pulsemcp.com/" target="_blank" rel="noopener noreferrer">PulseMCP (AIH recommended)</a> · <a href="https://mcpmarket.com/" target="_blank" rel="noopener noreferrer">MCP Market</a> · <a href="https://www.skills.sh/" target="_blank" rel="noopener noreferrer">Skills directory</a> · <a href="https://www.npmjs.com/search" target="_blank" rel="noopener noreferrer">npm</a> · <a href="https://github.com/search" target="_blank" rel="noopener noreferrer">GitHub</a>. AIH does not trust any directory as evidence.</p><div class="artifact-form-grid"><label>Default accountable owner email<input id="artifact-default-owner" type="email" placeholder="owner@company.example"></label><label>Artifact kind<select id="artifact-item-kind"><option value="mcp">MCP</option><option value="skill">Skill</option><option value="agent">Agent</option></select></label><label>Item identifier<input id="artifact-item-id" placeholder="firecrawl-mcp"></label><label>Discovery URL (optional)<input id="artifact-discovery-url" type="url" placeholder="https://..."></label><label>Exact source type<select id="artifact-source-type"><option value="npm">npm package</option><option value="github">GitHub</option></select></label></div><div class="artifact-form-grid" id="artifact-npm-fields"><label>Exact npm package<input id="artifact-npm-package" placeholder="package or @scope/package"></label><label>Exact version<input id="artifact-npm-version" placeholder="1.2.3"></label><label>Registry integrity (optional)<input id="artifact-npm-integrity" placeholder="sha512-..."></label></div><div class="artifact-form-grid" id="artifact-github-fields" hidden><label>Exact repository<input id="artifact-github-repository" placeholder="owner/repository"></label><label>Exact commit<input id="artifact-github-commit" placeholder="40-character commit"></label><label>Source path<input id="artifact-source-path" placeholder="skills/name/SKILL.md"></label></div><div class="brow"><button type="button" class="btn sm primary" id="add-artifact-item">Add to review queue</button><button type="button" class="btn sm" id="download-artifact-intake" disabled>Download one intake file</button></div><p class="help" id="artifact-intake-message"></p></section><section class="artifact-stage" aria-labelledby="artifact-scan-title"><h3 class="artifact-stage-title" id="artifact-scan-title">2. Scan unique exact sources</h3><pre class="mono" id="artifact-batch-command">aih trust scan aih-artifact-intake.json --apply --evidence-out aih-artifact-evidence.json</pre><p class="help">Run from the target root after downloading the intake. Scanner computes observed integrity, acquires duplicate exact sources once, and emits one evidence bundle. It does not approve, install, activate, choose targets, infer execution, or grant authority.</p></section><section class="artifact-stage" aria-labelledby="artifact-review-title"><h3 class="artifact-stage-title" id="artifact-review-title">3. Review evidence and continue to protected approval</h3><div class="artifact-queue-tools"><label>Filter the review queue<input id="artifact-queue-filter" type="search" placeholder="Filter by kind, identifier, source, owner, or status"></label><p class="help">Each intake or evidence file is limited to 1 MiB.</p></div><p class="help" id="artifact-intake-summary">0 / 100 candidates · no intake loaded.</p><div class="stack" id="artifact-intake-items"></div><p class="help"><b>Preflight only; fail closed.</b> Missing, malformed, stale, mismatched, replayed/conflicting, failed, and authority-absent states remain visible. Only verified preflight evidence can be carried into the separate protected approval step.</p></section>';
var sourceTypeField=card.querySelector("#artifact-source-type");var directoryOption=document.createElement("option");directoryOption.value="directory";directoryOption.textContent="Directory page (resolve first)";sourceTypeField.append(directoryOption);var directoryFields=document.createElement("div");directoryFields.className="artifact-form-grid";directoryFields.id="artifact-directory-fields";directoryFields.hidden=true;directoryFields.innerHTML='<label>PulseMCP or MCP Market server URL<input id="artifact-directory-url" type="url" maxlength="2048" placeholder="https://www.pulsemcp.com/servers/firecrawl"></label><p class="help">Add the directory page as a non-authoritative claim. Scanner will compare it with the official MCP Registry and return exact options for review. It will not install, approve, choose targets, or infer execution.</p>';var githubFields=card.querySelector("#artifact-github-fields");githubFields.after(directoryFields);card.querySelector("#artifact-add-title").textContent="1. Add sources or directory claims to the review queue";card.querySelector("#artifact-scan-title").textContent="2. Resolve claims and scan exact sources";
style.textContent+=".artifact-discovery-helper{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px 12px;align-items:end;padding:12px;border:1px solid var(--rule);border-radius:8px;background:var(--fill)}.artifact-discovery-helper[hidden]{display:none}.artifact-discovery-helper label{display:grid;gap:4px;min-width:0;color:var(--ink-3);font-size:var(--meta);text-wrap:pretty}.artifact-discovery-helper input{width:100%;min-width:0}.artifact-discovery-message{grid-column:1/-1;margin:0;white-space:pre-wrap;overflow-wrap:anywhere}#artifact-directory-fields .help{align-self:end;margin:0}.artifact-resolution-options{display:grid;gap:8px;margin-top:8px}.artifact-resolution-option{display:flex;gap:8px;align-items:center;justify-content:space-between;flex-wrap:wrap;padding:8px;border:1px solid var(--rule);border-radius:6px;background:var(--fill)}@media(max-width:900px){.artifact-discovery-helper{grid-template-columns:1fr}}";
