var mcpDiscoveryHelper=document.createElement("div");mcpDiscoveryHelper.id="artifact-mcp-discovery-helper";mcpDiscoveryHelper.className="artifact-discovery-helper";mcpDiscoveryHelper.hidden=true;mcpDiscoveryHelper.innerHTML='<label>Paste an MCP directory page, exact package command, npm page, or GitHub permalink<input id="artifact-mcp-discovery" type="text" maxlength="2048" placeholder="https://mcpmarket.com/server/name or npx -y package@1.2.3"></label><button type="button" class="btn sm" id="parse-mcp-discovery">Use discovery details</button><p class="help mono artifact-discovery-message" id="artifact-mcp-discovery-message">AIH parses the input locally and never runs or installs it. Directory pages become non-authoritative claims for official MCP Registry resolution; exact npm or GitHub pins populate the source fields for scanning.</p>';addStage.insertBefore(mcpDiscoveryHelper,firstFormGrid);
